import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Transportes atuais e restrições de plataforma","description":"","frontmatter":{"title":"Transportes atuais e restrições de plataforma","docId":"developer.transports","translationKey":"developer.transports","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a5fcd19211bdd279a0696cde31c26cc7444a128e50c3ca752489b25acb7cd9a","translationRevision":"19b77bfb15a322e68e2d62a2676095caff614488a78296902c86926f76d5378c","order":200},"headers":[],"relativePath":"pt/developer/transports.md","filePath":"pt/developer/transports.md","lastUpdated":1795735295000}`),a={name:`pt/developer/transports.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="current-transports-and-platform-restrictions" tabindex="-1">Transportes atuais e restrições de plataforma <a class="header-anchor" href="#current-transports-and-platform-restrictions" aria-label="Permalink to “Transportes atuais e restrições de plataforma”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Selecione o transporte que realmente existe para a compilação e plataforma de destino. Leia <a href="./control-api.html">API de controle</a> e <a href="./collaboration.html">colaboração</a>. Um transporte carrega operações serializadas; ele não deve introduzir um segundo núcleo nem conceder autoridade por si só.</p><h2 id="choose-the-boundary" tabindex="-1">Escolha o limite <a class="header-anchor" href="#choose-the-boundary" aria-label="Permalink to “Escolha o limite”">​</a></h2><table tabindex="0"><thead><tr><th>Caminho</th><th>Implementação atual</th><th>Limite importante</th></tr></thead><tbody><tr><td>WebView desktop</td><td>IPC Wry e cliente de controle compartilhado</td><td>Ciclo de vida da GUI/threads pertence ao desktop</td></tr><tr><td>CLI local</td><td>Socket Unix ou pipe nomeado do Windows; host stdio explícito</td><td>Mesmo diretório e proprietário do aplicativo</td></tr><tr><td>Navegador local</td><td>Adaptador loopback nativo mais <code>browser-transport.ts</code></td><td>Host nativo pareado, não um servidor remoto público</td></tr><tr><td>Gateway HTTPS/WSS autenticado</td><td>Transportes SDK/navegador com TLS, hello, concessões e feature gates</td><td>Comandos remotos exigem concessão explícita</td></tr><tr><td>Plugin de controle remoto instalável</td><td><code>tiktools.remote-control</code> sobre relay WSS com <code>remote.controller.ticket</code></td><td>Propriedade do plugin; nenhum código remoto é compilado no host</td></tr></tbody></table><p>A interface TypeScript fica em <code>src/web/shared/api/control-transport.ts</code>. O controle remoto é um plugin instalável, não parte do binário do host: todo comando passa por <code>HostCallPolicy</code> (<code>remote.command.dispatch</code>, <code>remote.pair.list</code>, <code>remote.grant.list</code>, <code>remote.grant.revoke</code>, <code>remote.controller.ticket</code>). Esta compilação não tem transporte peer/RTC nativo nem vínculo de host do Cloud Teams.</p><h2 id="inspect-the-selected-route" tabindex="-1">Inspecione a rota selecionada <a class="header-anchor" href="#inspect-the-selected-route" aria-label="Permalink to “Inspecione a rota selecionada”">​</a></h2><p>Descubra os métodos e capacidades suportados pelo host conectado antes de parear ou exibir uma ação de controle:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> browser-transport</span></span></code></pre></div><p>O pareamento e as concessões pertencem ao plugin: o ticket do controlador é de curta duração e uso único, e <code>remote.grant.list</code> / <code>remote.grant.revoke</code> são a visão autoritativa. Uma conexão de relay prova apenas o transporte, nunca autoridade RPC.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e estado”">​</a></h2><p>O IPC local e o transporte desktop são caminhos estabelecidos. O controle remoto funciona pelo plugin instalável e um relay autenticado; não é um segundo runtime de host. Os códigos de login são enviados aos dispositivos conectados com TTL de cinco minutos, com OAuth como alternativa quando nenhuma conta está configurada. O IPC local no Android funciona com as ferramentas instrumentadas <code>mobile</code> (<code>info</code> / <code>exec</code> / <code>tty</code>); addons nativos e WebViews de desktop continuam indisponíveis lá.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Trate a desconexão como possível incerteza para operações aceitas. A reconexão deve invalidar projeções privadas, renegociar a identidade e retomar ou capturar fluxos limitados. Nunca enfraqueça a verificação de certificados nem volte silenciosamente a um proprietário local após falha remota. Tickets expirados e concessões revogadas devem falhar fechados.</p><h2 id="operational-details" tabindex="-1">Detalhes operacionais <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes operacionais”">​</a></h2><p>Mantenha as concessões com privilégio mínimo e prazo limitado; verifique-as após cada reconexão. Diagnostique separadamente identidade, expiração do ticket, escopo da concessão, acessibilidade do relay e tamanho do quadro. Quadros grandes falham na validação de enquadramento, não geram RPCs parciais. Teste sessões alteradas/revogadas com fixtures antes da aceitação real com dois dispositivos.</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};